//! TypeThru for Windows: types the clipboard as key presses into VDI and remote desktops.
//! On other systems this builds a preview of the panel, for working on its look.
#![cfg_attr(windows, windows_subsystem = "windows")]

mod ui {
    #![allow(missing_debug_implementations, dead_code, clippy::all, clippy::unwrap_used)] // code generated by Slint
    slint::include_modules!();
}
use ui::Panel;

mod panel;
mod storage;

#[cfg(windows)]
mod controller;
#[cfg(windows)]
mod install;
#[cfg(windows)]
mod keyboard;
#[cfg(windows)]
mod native;
#[cfg(windows)]
mod screen_copy;
#[cfg(windows)]
mod settings_window;
#[cfg(windows)]
mod updater;

fn main() {
    #[cfg(windows)]
    controller::run();
    #[cfg(not(windows))]
    preview();
}

/// The panel with saved-nothing defaults and an opaque background; Quit or Esc closes it.
#[cfg(not(windows))]
fn preview() {
    use slint::ComponentHandle;
    // The keys of a US layout that TypeThru's standard shortcuts use.
    let character = |key| match key {
        0xDC => Some('\\'),
        0xDD => Some(']'),
        _ => char::from_u32(key).filter(char::is_ascii_alphanumeric),
    };
    let Ok(panel) = panel::create(&storage::load(), character) else { return };
    panel.set_solid(true);
    panel.set_on_top(false);
    panel.set_notice("Preview of the Windows panel. Buttons do nothing here.".into());
    panel.on_quit(|| {
        let _ = slint::quit_event_loop();
    });
    panel.on_dismiss(|| {
        let _ = slint::quit_event_loop();
    });
    panel.window().set_position(slint::LogicalPosition::new(200.0, 120.0));
    let _ = panel.run();
}
